import pytest
import pandas as pd
from code.classify_provenance import classify_row

def test_precedence_header_wins():
    """File-header attribution (overrides all)."""
    # Header says LLM, Commit says Human -> should be LLM-generated
    row = pd.Series({
        "file_headers": "@generated by AI",
        "diff_text": None,
        "commit_message": "Manually fixed a bug"
    })
    assert classify_row(row) == "LLM-generated"

def test_precedence_diff_wins_over_commit():
    """Diff-pattern matches override commit-message keywords."""
    # Header neutral, Diff says LLM, Commit says Human -> should be LLM-generated
    row = pd.Series({
        "file_headers": None,
        "diff_text": "This block was ai-generated",
        "commit_message": "Manual update"
    })
    assert classify_row(row) == "LLM-generated"

def test_commit_message_fallback():
    """Commit-message keywords apply if no higher-priority signal is present."""
    row = pd.Series({
        "file_headers": None,
        "diff_text": None,
        "commit_message": "Implemented using GitHub Copilot"
    })
    assert classify_row(row) == "LLM-generated"

def test_default_human():
    """No LLM signals -> Human-written."""
    row = pd.Series({
        "file_headers": "Author: Jane Doe",
        "diff_text": "Fixed typo",
        "commit_message": "Updated README"
    })
    assert classify_row(row) == "Human-written"

def test_mixed_conflict():
    """Conflicting LLM and human signals -> Mixed."""
    # Case 1: Different tiers conflict
    row1 = pd.Series({
        "file_headers": "@generated", # LLM
        "diff_text": None,
        "commit_message": "manually verified" # Human
    })
    assert classify_row(row1) == "Mixed"

    # Case 2: Single tier contains both
    row2 = pd.Series({
        "file_headers": None,
        "diff_text": None,
        "commit_message": "Copilot generated but manually edited"
    })
    assert classify_row(row2) == "Mixed"

def test_empty_fields():
    """Handle NaN/None gracefully."""
    row = pd.Series({
        "file_headers": np.nan,
        "diff_text": None,
        "commit_message": np.nan
    })
    assert classify_row(row) == "Human-written"

